def q(prova, numero, perfil, subject, topic, question, options, correct, explanation, option_explanations, fundamento):
    item = {
        "id": f"{PREFIXO}{prova}_{numero}",
        "subject": subject,
        "topic": topic,
        "source": f"Cesgranrio - BNDES (2024) - {PROVAS[prova]}, questão {numero}",
        "question": question,
        "options": options,
        "correct": correct,
        "explanation": explanation,
        "option_explanations": option_explanations,
        "fundamento": fundamento,
        "banca": "CESGRANRIO",
        "certame": "BNDES 2024",
        "nivel": "superior",
        "gabarito_oficial_conferido": True,
        "gabarito_status": "definitivo",
        "origem": URL_PAGINA,
    }
    item.update(perfil)
    return item


