def validar(item):
    letras = sorted(item["options"])
    assert letras == ["A", "B", "C", "D", "E"], f"{item['id']}: alternativas {letras}"
    assert item["correct"] in item["options"], f"{item['id']}: gabarito fora das alternativas"
    assert sorted(item["option_explanations"]) == letras, f"{item['id']}: justificativas incompletas"
    assert item["option_explanations"][item["correct"]].startswith("Correta"), f"{item['id']}: justificativa do gabarito"
    for letra, texto in item["option_explanations"].items():
        if letra != item["correct"]:
            assert not texto.startswith("Correta"), f"{item['id']}: alternativa {letra} marcada como correta"


def main():
    with open(ARQ, encoding="utf-8") as f:
        banco = json.load(f)

    backup = os.path.join(BASE, f"questions.backup_{date.today():%Y%m%d}_antes_cesgranrio.json")
    if not os.path.exists(backup):
        shutil.copyfile(ARQ, backup)

    for item in QUESTOES:
        validar(item)
    ids = [item["id"] for item in QUESTOES]
    assert len(ids) == len(set(ids)), "ids repetidos no lote"

    restantes = [x for x in banco if not str(x.get("id", "")).startswith(PREFIXO)]
    banco_novo = restantes + QUESTOES
    with open(ARQ, "w", encoding="utf-8") as f:
        json.dump(banco_novo, f, ensure_ascii=False, indent=2)

    print(f"Lote Cesgranrio BNDES 2024: {len(QUESTOES)} questões (banco: {len(restantes)} -> {len(banco_novo)})")
    print(f"Backup: {os.path.basename(backup)}")


if __name__ == "__main__":
    main()
